<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';require_once __DIR__.'/square_lib.php';tt_require_login();if($_SERVER['REQUEST_METHOD']!=='POST')tt_fail('POST required.',405,'Square checkout');tt_ad_check_csrf();$db=tt_db_open(false);if(!tt_ad_paid_schema_ready($db)){$db->close();tt_fail('Paid-ad schema is not installed yet. Run the protected database migration once.',503,'Square checkout');}if(!tt_square_ready()){$db->close();tt_fail('Square checkout is not configured on this host yet.',503,'Square checkout');}
$uid=(int)$_SESSION['id'];$idem=bin2hex(random_bytes(24));$credits=tt_square_ad_package_credits();$cents=tt_square_ad_package_cents();$env=tt_square_env();
try{$s=tt_prepare($db,"INSERT INTO `square_ad_purchases` (`account_id`,`environment`,`idempotency_key`,`amount_cents`,`credits`,`status`,`created_at`) VALUES (?,?,?,?,?,'pending',UTC_TIMESTAMP())");$s->bind_param('issii',$uid,$env,$idem,$cents,$credits);if(!$s->execute())throw new RuntimeException($s->error);$purchase=(int)$db->insert_id;$s->close();
 $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'https';$host=(string)($_SERVER['HTTP_HOST']??'eski-web.org');$returnUrl=$scheme.'://'.$host.'/tabletime/adcredits.php?square_return=1';
 $body=['idempotency_key'=>$idem,'description'=>'Tabletime Ads: 1000 funded impressions','order'=>['location_id'=>tt_square_location_id(),'line_items'=>[['quantity'=>'1','catalog_object_id'=>tt_square_ad_variation_id()]]],'payment_note'=>'tabletime-ad-purchase:'.$purchase.':account:'.$uid,'checkout_options'=>['redirect_url'=>$returnUrl]];
 $r=tt_square_request('POST','/v2/online-checkout/payment-links',$body);$pl=$r['payment_link']??[];$linkId=(string)($pl['id']??'');$orderId=(string)($pl['order_id']??'');$url=(string)($pl['url']??'');if($linkId===''||$orderId===''||$url==='')throw new RuntimeException('Square did not return a usable payment link.');$s=tt_prepare($db,'UPDATE `square_ad_purchases` SET `payment_link_id`=?,`order_id`=? WHERE `id`=?');$s->bind_param('ssi',$linkId,$orderId,$purchase);$s->execute();$s->close();$db->close();header('Location: '.$url,true,303);exit;
}catch(Throwable $e){if(isset($purchase)&&$purchase>0){$msg=substr($e->getMessage(),0,500);$s=$db->prepare("UPDATE `square_ad_purchases` SET `status`='failed',`last_error`=? WHERE `id`=?");if($s){$s->bind_param('si',$msg,$purchase);@$s->execute();$s->close();}}$db->close();tt_fail('Could not start Square checkout: '.$e->getMessage(),502,'Square checkout');}
